-- Vivafit · Alimentação brasileira, caseira e simples
-- Migração NÃO destrutiva: nenhum DELETE, nenhum DROP, nenhum dado de usuária alterado.
begin;

-- 1) Novos campos opcionais em receitas
alter table public.recipes add column if not exists servings int;
alter table public.recipes add column if not exists image_url text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'recipes_servings_positive') then
    alter table public.recipes add constraint recipes_servings_positive check (servings is null or servings > 0);
  end if;
end $$;

-- 2) Favoritos por usuária (cada uma só vê e altera os próprios)
create table if not exists public.recipe_favorites (
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  recipe_id uuid not null references public.recipes(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, recipe_id)
);
grant select, insert, delete on public.recipe_favorites to authenticated;
grant all on public.recipe_favorites to service_role;
alter table public.recipe_favorites enable row level security;
drop policy if exists "own favorites read" on public.recipe_favorites;
drop policy if exists "own favorites insert" on public.recipe_favorites;
drop policy if exists "own favorites delete" on public.recipe_favorites;
create policy "own favorites read" on public.recipe_favorites for select to authenticated using (user_id = auth.uid());
create policy "own favorites insert" on public.recipe_favorites for insert to authenticated with check (user_id = auth.uid());
create policy "own favorites delete" on public.recipe_favorites for delete to authenticated using (user_id = auth.uid());

-- 3) Receitas antigas: só despublicadas (continuam no banco; podem voltar com published = true)
update public.recipes set published = false
where published = true
  and title not in ('Pão com ovo mexido', 'Tapioca com queijo e tomate', 'Cuscuz com ovo', 'Mingau de aveia com banana', 'Vitamina de banana com aveia', 'Salada de frutas', 'Frango grelhado com arroz e feijão', 'Feijão caseiro na pressão', 'Carne moída com legumes', 'Peixe assado com batata', 'Salada de alface, tomate e cenoura', 'Legumes refogados', 'Sanduíche natural de frango', 'Iogurte com banana e aveia', 'Ovo cozido com fruta', 'Pão de queijo de frigideira', 'Banana amassada com aveia e canela', 'Torrada com requeijão e tomate', 'Omelete de legumes', 'Sopa de legumes com frango', 'Frango desfiado com legumes', 'Caldo verde simples', 'Arroz mexido com ovo e legumes', 'Caldo de feijão');

-- 4) Receitas brasileiras (só insere as que ainda não existem — pode rodar de novo sem duplicar)
insert into public.recipes
  (title, description, meal_type, prep_minutes, servings, calories, protein, carbs, fat, tags, ingredients, steps, premium, published)
select v.* from (values
  ('Pão com ovo mexido', 'O clássico da padaria, feito em casa em poucos minutos.', 'cafe', 10, 1, 330, 17, 30, 15, array['vegetariana']::text[], '[{"name": "Pão francês", "qty": "1 unidade"}, {"name": "Ovos", "qty": "2 unidades"}, {"name": "Manteiga ou óleo", "qty": "1 colher (chá)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Bata os ovos com uma pitada de sal.', 'Aqueça a manteiga numa frigideira em fogo baixo e despeje os ovos.', 'Mexa devagar até ficarem cremosos e cozidos.', 'Abra o pão, recheie com o ovo e sirva.']::text[], false, true),
  ('Tapioca com queijo e tomate', 'Rápida, sem glúten e boa para começar o dia.', 'cafe', 10, 1, 260, 11, 35, 8, array['vegetariana', 'sem_gluten']::text[], '[{"name": "Goma de tapioca hidratada", "qty": "3 colheres (sopa)"}, {"name": "Queijo minas ou muçarela", "qty": "2 fatias"}, {"name": "Tomate", "qty": "½ unidade em rodelas"}, {"name": "Orégano", "qty": "a gosto"}]'::jsonb, array['Espalhe a goma numa frigideira antiaderente, em fogo médio, sem óleo.', 'Quando as bordas soltarem, vire com cuidado.', 'Coloque o queijo e o tomate em metade da tapioca e salpique orégano.', 'Dobre ao meio e deixe mais 1 minuto para o queijo derreter.']::text[], false, true),
  ('Cuscuz com ovo', 'Cuscuz de milho na cuscuzeira, com ovo por cima.', 'cafe', 15, 2, 280, 10, 40, 8, array['vegetariana', 'sem_gluten']::text[], '[{"name": "Flocão de milho", "qty": "1 xícara (chá)"}, {"name": "Água", "qty": "½ xícara (chá)"}, {"name": "Sal", "qty": "1 pitada"}, {"name": "Ovos", "qty": "2 unidades"}, {"name": "Manteiga", "qty": "1 colher (chá)"}]'::jsonb, array['Misture o flocão com a água e o sal e deixe hidratar por 5 minutos.', 'Coloque água no fundo da cuscuzeira, acomode a massa sem apertar e tampe.', 'Cozinhe por cerca de 8 minutos depois que começar a sair vapor.', 'Enquanto isso, frite ou cozinhe os ovos.', 'Sirva o cuscuz com a manteiga e o ovo por cima.']::text[], false, true),
  ('Mingau de aveia com banana', 'Quentinho, simples e com ingredientes de casa.', 'cafe', 10, 1, 300, 11, 50, 7, array['vegetariana']::text[], '[{"name": "Aveia em flocos", "qty": "3 colheres (sopa)"}, {"name": "Leite", "qty": "1 xícara (chá)"}, {"name": "Banana", "qty": "1 unidade"}, {"name": "Canela em pó", "qty": "a gosto"}]'::jsonb, array['Leve o leite e a aveia ao fogo baixo, mexendo sempre.', 'Cozinhe por 3 a 5 minutos, até engrossar.', 'Desligue, coloque numa tigela e cubra com a banana em rodelas.', 'Polvilhe canela e sirva.']::text[], false, true),
  ('Vitamina de banana com aveia', 'Pronta no liquidificador em 5 minutos.', 'cafe', 5, 1, 280, 10, 48, 6, array['vegetariana']::text[], '[{"name": "Banana", "qty": "1 unidade"}, {"name": "Leite", "qty": "1 copo (200 ml)"}, {"name": "Aveia em flocos", "qty": "1 colher (sopa)"}, {"name": "Mel ou açúcar", "qty": "1 colher (chá), opcional"}]'::jsonb, array['Coloque todos os ingredientes no liquidificador.', 'Bata por cerca de 1 minuto, até ficar cremoso.', 'Sirva na hora.']::text[], false, true),
  ('Salada de frutas', 'Use as frutas que estiverem mais baratas na semana.', 'cafe', 10, 2, 120, 2, 30, 1, array['vegana', 'sem_gluten', 'sem_lactose']::text[], '[{"name": "Banana", "qty": "1 unidade"}, {"name": "Maçã", "qty": "1 unidade"}, {"name": "Laranja", "qty": "1 unidade"}, {"name": "Mamão", "qty": "1 fatia"}, {"name": "Limão", "qty": "suco de ½ unidade"}]'::jsonb, array['Lave bem as frutas.', 'Corte tudo em cubos pequenos, sem a casca da laranja e do mamão.', 'Misture numa tigela e regue com o suco de limão para não escurecer.', 'Sirva na hora ou guarde na geladeira por até 1 dia.']::text[], false, true),
  ('Frango grelhado com arroz e feijão', 'O prato feito de todo dia, leve e bem temperado.', 'almoco', 30, 2, 520, 42, 60, 11, array['sem_gluten', 'sem_lactose']::text[], '[{"name": "Filé de peito de frango", "qty": "2 unidades (cerca de 300 g)"}, {"name": "Alho", "qty": "1 dente amassado"}, {"name": "Limão", "qty": "suco de ½ unidade"}, {"name": "Óleo ou azeite", "qty": "1 colher (sopa)"}, {"name": "Sal", "qty": "a gosto"}, {"name": "Arroz cozido", "qty": "2 xícaras (chá)"}, {"name": "Feijão cozido", "qty": "2 conchas"}]'::jsonb, array['Tempere o frango com alho, limão e sal e deixe descansar por 10 minutos.', 'Aqueça uma frigideira com o óleo em fogo médio.', 'Grelhe o frango por 5 a 6 minutos de cada lado, até dourar e cozinhar por dentro.', 'Sirva com o arroz e o feijão.']::text[], false, true),
  ('Feijão caseiro na pressão', 'Rende para a semana toda e pode ser congelado.', 'almoco', 40, 6, 140, 9, 24, 2, array['vegana', 'sem_gluten', 'sem_lactose']::text[], '[{"name": "Feijão carioca", "qty": "2 xícaras (chá)"}, {"name": "Água", "qty": "6 xícaras (chá)"}, {"name": "Cebola", "qty": "½ unidade picada"}, {"name": "Alho", "qty": "2 dentes amassados"}, {"name": "Folha de louro", "qty": "1 unidade"}, {"name": "Óleo", "qty": "1 colher (sopa)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Escolha e lave o feijão. Se der, deixe de molho por algumas horas e descarte a água.', 'Coloque o feijão, a água e o louro na panela de pressão. Cozinhe por 25 minutos após pegar pressão.', 'Espere a pressão sair. Numa frigideira, refogue a cebola e o alho no óleo.', 'Junte o refogado ao feijão, acerte o sal e deixe ferver mais 5 minutos sem tampa.']::text[], false, true),
  ('Carne moída com legumes', 'Rende bem e combina com arroz, purê ou macarrão.', 'almoco', 25, 3, 280, 24, 9, 16, array['sem_gluten', 'sem_lactose', 'low_carb']::text[], '[{"name": "Carne moída", "qty": "300 g"}, {"name": "Cebola", "qty": "1 unidade picada"}, {"name": "Tomate", "qty": "1 unidade picado"}, {"name": "Cenoura", "qty": "1 unidade ralada"}, {"name": "Abobrinha", "qty": "½ unidade picada"}, {"name": "Óleo", "qty": "1 colher (sopa)"}, {"name": "Cheiro-verde", "qty": "a gosto"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Refogue a cebola no óleo até ficar transparente.', 'Junte a carne e mexa até perder a cor vermelha.', 'Acrescente o tomate, a cenoura e a abobrinha. Tempere com sal.', 'Tampe e cozinhe por 10 minutos em fogo baixo. Finalize com cheiro-verde.']::text[], false, true),
  ('Peixe assado com batata', 'Tudo numa assadeira só: menos louça, mais sabor.', 'almoco', 35, 2, 360, 30, 32, 11, array['sem_gluten', 'sem_lactose']::text[], '[{"name": "Filé de tilápia", "qty": "2 unidades"}, {"name": "Batata", "qty": "2 unidades médias em rodelas"}, {"name": "Cebola", "qty": "½ unidade em rodelas"}, {"name": "Limão", "qty": "suco de 1 unidade"}, {"name": "Azeite ou óleo", "qty": "1 colher (sopa)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Tempere o peixe com limão e sal.', 'Forre a assadeira com as batatas e a cebola, regue com azeite e salgue.', 'Leve ao forno a 200 °C por 15 minutos.', 'Coloque o peixe por cima e asse mais 15 minutos, até ficar branquinho e soltar em lascas.']::text[], false, true),
  ('Salada de alface, tomate e cenoura', 'A salada do dia a dia, pronta em 10 minutos.', 'almoco', 10, 2, 70, 2, 10, 3, array['vegana', 'sem_gluten', 'sem_lactose', 'low_carb']::text[], '[{"name": "Alface", "qty": "½ pé"}, {"name": "Tomate", "qty": "1 unidade"}, {"name": "Cenoura", "qty": "1 unidade ralada"}, {"name": "Limão", "qty": "suco de ½ unidade"}, {"name": "Azeite", "qty": "1 colher (chá)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Lave bem as folhas e os legumes.', 'Rasgue a alface com as mãos e corte o tomate em gomos.', 'Junte a cenoura ralada.', 'Tempere na hora de servir com limão, azeite e sal.']::text[], false, true),
  ('Legumes refogados', 'Abobrinha, cenoura e chuchu para acompanhar qualquer prato.', 'almoco', 20, 3, 90, 2, 12, 4, array['vegana', 'sem_gluten', 'sem_lactose', 'low_carb']::text[], '[{"name": "Abobrinha", "qty": "1 unidade em cubos"}, {"name": "Cenoura", "qty": "1 unidade em rodelas"}, {"name": "Chuchu", "qty": "1 unidade em cubos"}, {"name": "Alho", "qty": "1 dente picado"}, {"name": "Óleo ou azeite", "qty": "1 colher (sopa)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Refogue o alho no óleo por 1 minuto.', 'Junte a cenoura e o chuchu, que demoram mais, e mexa por 3 minutos.', 'Acrescente a abobrinha, o sal e 2 colheres de água. Tampe.', 'Cozinhe por 8 a 10 minutos, até ficarem macios mas firmes.']::text[], false, true),
  ('Sanduíche natural de frango', 'Ótimo para levar na bolsa ou na marmita.', 'lanche', 10, 2, 300, 22, 28, 10, '{}'::text[], '[{"name": "Pão de forma", "qty": "4 fatias"}, {"name": "Frango cozido e desfiado", "qty": "1 xícara (chá)"}, {"name": "Requeijão", "qty": "2 colheres (sopa)"}, {"name": "Cenoura", "qty": "½ unidade ralada"}, {"name": "Alface", "qty": "2 folhas"}]'::jsonb, array['Misture o frango com o requeijão e a cenoura.', 'Espalhe o recheio em 2 fatias de pão.', 'Coloque a alface e feche com as outras fatias.', 'Corte ao meio e sirva, ou embale para levar.']::text[], false, true),
  ('Iogurte com banana e aveia', 'Lanche de 3 minutos, sem fogão.', 'lanche', 3, 1, 220, 9, 35, 5, array['vegetariana']::text[], '[{"name": "Iogurte natural", "qty": "1 pote (170 g)"}, {"name": "Banana", "qty": "½ unidade"}, {"name": "Aveia em flocos", "qty": "1 colher (sopa)"}, {"name": "Mel", "qty": "1 colher (chá), opcional"}]'::jsonb, array['Coloque o iogurte numa tigela.', 'Corte a banana em rodelas por cima.', 'Finalize com a aveia e, se quiser, o mel.']::text[], false, true),
  ('Ovo cozido com fruta', 'Prático, barato e sustenta até a próxima refeição.', 'lanche', 12, 1, 220, 13, 18, 10, array['vegetariana', 'sem_gluten', 'sem_lactose']::text[], '[{"name": "Ovos", "qty": "2 unidades"}, {"name": "Fruta da estação", "qty": "1 unidade"}, {"name": "Sal", "qty": "1 pitada"}]'::jsonb, array['Coloque os ovos numa panela, cubra com água e leve ao fogo.', 'Quando ferver, conte 9 minutos.', 'Passe os ovos para água fria, descasque e tempere com uma pitada de sal.', 'Sirva com a fruta.']::text[], false, true),
  ('Pão de queijo de frigideira', 'Sabor de pão de queijo, pronto em 10 minutos.', 'lanche', 10, 1, 230, 12, 22, 10, array['vegetariana', 'sem_gluten']::text[], '[{"name": "Ovo", "qty": "1 unidade"}, {"name": "Goma de tapioca", "qty": "2 colheres (sopa)"}, {"name": "Queijo ralado", "qty": "2 colheres (sopa)"}, {"name": "Leite", "qty": "1 colher (sopa)"}, {"name": "Sal", "qty": "1 pitada"}]'::jsonb, array['Misture todos os ingredientes num prato fundo com um garfo.', 'Despeje numa frigideira antiaderente pequena, em fogo baixo, e tampe.', 'Quando a parte de baixo dourar, vire e doure o outro lado.', 'Sirva quente.']::text[], false, true),
  ('Banana amassada com aveia e canela', 'Doce natural, sem açúcar e sem fogão.', 'lanche', 3, 1, 170, 4, 36, 2, array['vegana', 'sem_lactose']::text[], '[{"name": "Banana bem madura", "qty": "1 unidade"}, {"name": "Aveia em flocos", "qty": "1 colher (sopa)"}, {"name": "Canela em pó", "qty": "a gosto"}]'::jsonb, array['Amasse a banana com um garfo.', 'Misture a aveia.', 'Polvilhe canela e sirva.']::text[], false, true),
  ('Torrada com requeijão e tomate', 'Para a tarde, com café ou chá.', 'lanche', 5, 1, 200, 7, 26, 7, array['vegetariana']::text[], '[{"name": "Pão de forma ou francês", "qty": "2 fatias"}, {"name": "Requeijão", "qty": "1 colher (sopa)"}, {"name": "Tomate", "qty": "½ unidade em rodelas"}, {"name": "Orégano", "qty": "a gosto"}]'::jsonb, array['Torre o pão na frigideira ou na torradeira.', 'Espalhe o requeijão.', 'Cubra com o tomate e salpique orégano.']::text[], false, true),
  ('Omelete de legumes', 'Leve, rápida e boa para aproveitar o que tem na geladeira.', 'jantar', 15, 1, 210, 14, 6, 14, array['vegetariana', 'sem_gluten', 'sem_lactose', 'low_carb']::text[], '[{"name": "Ovos", "qty": "2 unidades"}, {"name": "Tomate", "qty": "½ unidade picado"}, {"name": "Cebola", "qty": "2 colheres (sopa) picada"}, {"name": "Cheiro-verde", "qty": "a gosto"}, {"name": "Óleo", "qty": "1 colher (chá)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Bata os ovos com o sal.', 'Misture o tomate, a cebola e o cheiro-verde.', 'Despeje numa frigideira untada, em fogo baixo, e tampe.', 'Quando firmar, dobre ao meio e sirva.']::text[], false, true),
  ('Sopa de legumes com frango', 'Reconfortante e rende bem para a família.', 'jantar', 35, 4, 200, 16, 22, 4, array['sem_gluten', 'sem_lactose']::text[], '[{"name": "Peito de frango em cubos", "qty": "200 g"}, {"name": "Batata", "qty": "2 unidades em cubos"}, {"name": "Cenoura", "qty": "1 unidade em cubos"}, {"name": "Chuchu", "qty": "1 unidade em cubos"}, {"name": "Cebola", "qty": "½ unidade picada"}, {"name": "Alho", "qty": "2 dentes"}, {"name": "Água", "qty": "1 litro"}, {"name": "Sal e cheiro-verde", "qty": "a gosto"}]'::jsonb, array['Refogue a cebola e o alho numa panela com um fio de óleo.', 'Junte o frango e mexa até dourar levemente.', 'Acrescente os legumes, a água e o sal.', 'Cozinhe por 20 minutos, até a batata ficar macia. Finalize com cheiro-verde.']::text[], false, true),
  ('Frango desfiado com legumes', 'Serve no prato, no pão ou na tapioca.', 'jantar', 30, 3, 240, 28, 8, 10, array['sem_gluten', 'sem_lactose', 'low_carb']::text[], '[{"name": "Peito de frango", "qty": "400 g"}, {"name": "Cebola", "qty": "1 unidade picada"}, {"name": "Tomate", "qty": "1 unidade picado"}, {"name": "Cenoura", "qty": "1 unidade ralada"}, {"name": "Óleo", "qty": "1 colher (sopa)"}, {"name": "Sal e cheiro-verde", "qty": "a gosto"}]'::jsonb, array['Cozinhe o frango em água com sal por 20 minutos (ou 10 na pressão).', 'Escorra e desfie com dois garfos.', 'Refogue a cebola no óleo, junte o tomate e a cenoura.', 'Acrescente o frango, mexa por 3 minutos e finalize com cheiro-verde.']::text[], false, true),
  ('Caldo verde simples', 'Batata e couve: barato, quentinho e saboroso.', 'jantar', 30, 4, 180, 4, 30, 5, array['vegana', 'sem_gluten', 'sem_lactose']::text[], '[{"name": "Batata", "qty": "4 unidades"}, {"name": "Couve", "qty": "1 maço fatiado bem fininho"}, {"name": "Cebola", "qty": "½ unidade"}, {"name": "Alho", "qty": "2 dentes"}, {"name": "Azeite ou óleo", "qty": "1 colher (sopa)"}, {"name": "Água", "qty": "1 litro"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Cozinhe as batatas, a cebola e o alho na água com sal até ficarem bem macios.', 'Bata tudo no liquidificador (cuidado: espere amornar um pouco).', 'Volte o creme para a panela e junte a couve.', 'Deixe ferver por 3 minutos e regue com o azeite.']::text[], false, true),
  ('Arroz mexido com ovo e legumes', 'Aproveita o arroz que sobrou do almoço.', 'jantar', 15, 2, 320, 13, 48, 8, array['vegetariana', 'sem_lactose']::text[], '[{"name": "Arroz cozido", "qty": "2 xícaras (chá)"}, {"name": "Ovos", "qty": "2 unidades"}, {"name": "Cenoura", "qty": "1 unidade ralada"}, {"name": "Milho ou ervilha", "qty": "½ xícara (chá)"}, {"name": "Cebolinha", "qty": "a gosto"}, {"name": "Óleo", "qty": "1 colher (chá)"}, {"name": "Sal", "qty": "a gosto"}]'::jsonb, array['Refogue a cenoura no óleo por 2 minutos.', 'Junte o arroz e o milho e mexa até aquecer.', 'Abra um espaço na panela, quebre os ovos e mexa até cozinharem.', 'Misture tudo, acerte o sal e finalize com cebolinha.']::text[], false, true),
  ('Caldo de feijão', 'Usa o feijão de casa e fica pronto em 20 minutos.', 'jantar', 20, 3, 180, 10, 28, 3, array['vegana', 'sem_gluten', 'sem_lactose']::text[], '[{"name": "Feijão cozido com caldo", "qty": "3 conchas"}, {"name": "Água", "qty": "1 xícara (chá)"}, {"name": "Alho", "qty": "1 dente"}, {"name": "Cebola", "qty": "¼ unidade"}, {"name": "Óleo", "qty": "1 colher (chá)"}, {"name": "Cheiro-verde", "qty": "a gosto"}]'::jsonb, array['Bata o feijão com a água no liquidificador.', 'Refogue o alho e a cebola no óleo.', 'Junte o feijão batido e deixe ferver por 10 minutos, mexendo de vez em quando.', 'Finalize com cheiro-verde.']::text[], false, true)
) as v(title, description, meal_type, prep_minutes, servings, calories, protein, carbs, fat, tags, ingredients, steps, premium, published)
where not exists (select 1 from public.recipes r where r.title = v.title);

commit;
